import pytest
import project
import project.stats as stats

def test_exports():
    assert project.weighted_mean is stats.weighted_mean
@pytest.mark.parametrize("values,weights,expected", [
    ([1, 5], [1, 3], 4), ([1, 9], [0, 2], 9), ([-2, 4], [1, 1], 1)])
def test_weighted(values, weights, expected):
    assert project.weighted_mean(values, weights) == pytest.approx(expected)
@pytest.mark.parametrize("values,weights", [
    ([], []), ([1, 2], [1]), ([1], [-1]), ([1, 2], [0, 0])])
def test_invalid(values, weights):
    with pytest.raises(ValueError):
        project.weighted_mean(values, weights)
